ange(residuals.shape[0]):\n1153:         source = residuals[level, :batch_size]\n1154:         candidates = residuals[level, batch_size:]\n1155:         logits = heads.project_source(source) @ heads.project_target(candidates).T\n1156:         if symmetric:\n1157:             reverse = heads.project_source(candidates) @ heads.project_target(source).T\n1158:             logits = 0.5 * (logits + reverse)\n1159:         logits = logits / BEHAVIOR_TEMPERATURE\n1160:         loss = _contrastive_ce(logits, source_ids, target_ids, successor_indicator)\n1161:         if loss is not None:\n1162:             losses.append(loss)\n1163:     if not losses:\n1164:         return residuals.sum() * 0.0\n1165:     return torch.stack(losses).mean()\n1166: \n1167: def _tokenizer_config() -> SimpleNamespace:\n1168:     sizes = list(CODEBOOK_SIZE)\n1169:     if len(sizes) == 1:\n1170:         sizes *= CODEBOOK_NUM\n1171:     if len(sizes) != CODEBOOK_NUM:\n1172:         raise ValueError(\"CODEBOOK_SIZE must contain one size or one size per codebook level\")\n1173:     return SimpleNamespace(\n1174:         # the role-assigned level: level 2 quantises the behaviour factor, not the residual's\n1175:         # remainder, and contributes nothing to the reconstruction (-1 is the host's chain)\n1176:         role_level=2,\n1177:         hidden_sizes=HIDDEN_SIZES,\n1178:         codebook_num=CODEBOOK_NUM,\n1179:         codebook_size=tuple(sizes),\n1180:         codebook_dim=CODEBOOK_DIM,\n1181:         dropout=0.0,\n1182:         beta=BETA,\n1183:         vq_type=VQ_TYPE,\n1184:         ema_decay=EMA_DECAY,\n1185:         fix_code_embs=False,\n1186:         sk_epsilon=SK_EPSILON,\n1187:         sk_iters=SK_ITERS,\n1188:     )\n1189: \n1190: \n1191: def _behaviour_factors(model, embeddings: torch.Tensor, pairs: np.ndarray) -> torch.Tensor:\n1192:     \"\"\"The role signal for the role-assigned level: the direction to the mean successor.\n1193: \n1194:     b(x) = normalise(mean_{y in succ(x)} phi(y) - phi(x)), where phi is the model's ENCODER and\n1195:     succ(x) are the items that follow x in a user history, taken from the trainer's own pair\n1196:     stream. The signal lives in the model's own 32-dimensional latent space, so the role\n1197:     level's codebook keeps the frozen capacity (three levels, 256 codes, 32 dimensions).\n1198: \n1199:     It is recomputed from the current encoder, so the role token is learned jointly with the\n1200:     content levels rather than being a fixed catalogue label. An item with no successor takes\n1201:     the mean direction, so the assignment stays deterministic.\n1202:     \"\"\"\n1203:     n_items = int(embeddings.shape[0])\n1204:     was_training = model.training\n1205:     model.eval()\n1206:     try:\n1207:         with torch.no_grad():\n1208:             latent = model.encoder(embeddings)\n1209:     finally:\n1210:         if was_training:\n1211:             model.train()\n1212:     source = torch.as_tensor(np.asarray(pairs)[:, 0], dtype=torch.long, device=latent.device)\n1213:     target = torch.as_tensor(np.asarray(pairs)[:, 1], dtype=torch.long, device=latent.device)\n1214:     keep = (source >= 0) & (source < n_items) & (target >= 0) & (target < n_items)\n1215:     source, target = source[keep], target[keep]\n1216:     if source.numel() == 0:\n1217:         raise RuntimeError(\"the training parquet produced no successor pairs\")\n1218:     sums = torch.zeros_like(latent)\n1219:     counts = torch.zeros(n_items, dtype=latent.dtype, device=latent.device)\n1220:     sums.index_add_(0, target, latent[source])\n1221:     counts.index_add_(0, target, torch.ones(target.numel(), dtype=latent.dtype,\n1222:                                              device=latent.device))\n1223:     has = counts > 0\n1224:     factors = torch.zeros_like(latent)\n1225:     factors[has] = torch.nn.functional.normalize(sums[has] / counts[has].unsqueeze(1), dim=1)\n1226:     fallback = torch.nn.functional.normalize(factors[has].mean(dim=0), dim=0)\n1227:     factors[~has] = fallback\n1228:     return factors\n1229: \n1230: \n1231: def _probe_role_inputs(model, embeddings: torch.Tensor) -> torch.Tensor:\n1232:     \"\"\"The role signal for a probe case: the REAL helper, on a deterministic pair set.\n1233: \n1234:     The CGV's probe rows are synthetic, so the successor set is the deterministic cycle\n1235:     (i -> i+1). The helper is the training one, so the probe exercises the same code path.\n1236:     \"\"\"\n1237:     n = int(embeddings.shape[0])\n1238:     pairs = np.stack([np.arange(n), (np.arange(n) + 1) % n], axis=1)\n1239:     return _behaviour_factors(model, embeddings, pairs)\n1240: \n1241: \n1242: def _role_level_loss(model, embeddings: torch.Tensor, role_inputs: torch.Tensor) -> torch.Tensor:\n1243:     \"\"\"The role level's own quantisation loss: the commitment on the behaviour factor.\n1244: \n1245:     This is the exact call the training makes for the role level, so the CGV's gradient gates\n1246:     measure the term that actually trains that codebook.\n1247:     \"\"\"\n1248:     level = int(model.rq.role_level)\n1249:     if level < 0:\n1250:         raise ValueError(\"this model has no role-assigned level\")\n1251:     _, loss, _, _ = model.rq.vq_layers[level](role_inputs)\n1252:     return loss\n1253: \n1254: \n1255: def _role_term_provider(obs) -> torch.Tensor:\n1256:     \"\"\"The mechanism's term, on the verifier's observations: the role level's own loss.\n1257: \n1258:     The provider is called by the verifier, not by the training, and its result is handed to\n1259:     the executor as the mechanism's inputs. It is the exact call the training makes for the\n1260:     role level, so the gradient gates measure the term that trains that codebook.\n1261:     \"\"\"\n1262:     model = obs[\"model\"]\n1263:     role_inputs = obs[\"role_inputs\"]\n1264:     if role_inputs is None:\n1265:         raise ValueError(\"the role term needs the role inputs, which were not observed\")\n1266:     level = int(model.rq.role_level)\n1267:     _, loss, _, _ = model.rq.vq_layers[level](role_inputs)\n1268:     return loss\n1269: \n1270: \n1271: def _role_executor(base_loss, l1_loss, other_loss, encoder, weight, valid_levels=0,\n1272:                    *, mechanism_inputs=None, **kwargs) -> torch.Tensor:\n1273:     \"\"\"The role-assigned layout's contribution to the loss assembly: exactly ZERO.\n1274: \n1275:     The layout is a change of what a level quantises, not a new loss: the role level's\n1276:     commitment is already inside the quantisation loss the host computes, so folding the role\n1277:     term in again would double it. The mechanism's term is therefore measured directly (the\n1278:     declared loss term ``role_loss``), and the assembly itself contributes nothing.\n1279:     \"\"\"\n1280:     if mechanism_inputs is None:\n1281:         raise ValueError(\"the role executor needs the mechanism's inputs\")\n1282:     return torch.zeros((), dtype=base_loss.dtype, device=base_loss.device)\n1283: \n1284: \n1285: def main() -> None:\n1286:     # === 运行模式: 单卡 (one process) 或 4 卡 DDP ===\n1287:     single_gpu = resolve_single_gpu()\n1288:     # === DDP 初始化 ===\n1289:     if \"RANK\" in os.environ and int(os.environ.get(\"RANK\", -1)) >= 0:\n1290:         dist.init_process_group(backend=\"nccl\")\n1291:         rank = dist.get_rank()\n1292:         world_size = dist.get_world_size()\n1293:         local_rank = int(os.environ.get(\"LOCAL_RANK\", rank))\n1294:         torch.cuda.set_device(local_rank)\n1295:         device = torch.device(f\"cuda:{local_rank}\")\n1296:     else:\n1297:         rank, world_size, local_rank = 0, 1, 0\n1298:         device = torch.device(\"cuda:0\" if torch.cuda.is_available() else \"cpu\")\n1299:     # 单卡时: 一个进程承担 4 卡的全局 batch (每进程 1024 -> 4096, 512 -> 2048), 于是全局\n1300:     # item batch 相同; 多卡时每进程仍是 1024/512, 全局 batch 由 world_size 相乘 ——\n1301:     # 与改动前逐值相同。注意这不是轨迹等价: 采样分片/补齐、随机数流、float 累加顺序\n1302:     # 都不同, 这里只保证超参与名义全局 batch 不变。\n1303:     batch_scale = REFERENCE_WORLD_SIZE if single_gpu else 1\n1304:     loader_item_batch = BATCH_SIZE_PER_RANK * batch_scale\n1305:     loader_pair_batch = PAIR_BATCH_SIZE_PER_RANK * batch_scale\n1306:     global_item_batch = loader_item_batch * world_size\n1307:     global_pair_batch = loader_pair_batch * world_size\n1308: \n1309:     set_seed(SEED + rank)\n1310:     embeddings = maybe_apply_pca(load_embeddings(EMBEDDING_FILE), PCA_DIM, SEED)\n1311:     train_frame = pd.read_parquet(TRAIN_FILE)\n1312:     train_ids = np.unique(train_frame[\"target\"].to_numpy(dtype=np.int64))\n1313:     if train_ids.size == 0 or train_ids.min() < 0 or train_ids.max() >= len(embeddings):\n1314:         raise ValueError(\"Training target item ids do not match the embedding rows\")\n1315: \n1316:     geometry_bucket_padded_t = geometry_item_bucket_t = None\n1317:     if _GEOMETRY_CONFIG is not None:\n1318:         _, _, _, geometry_popularity, _ = _successor_counts(\n1319:             train_frame, len(embeddings)\n1320:         )\n1321:         geometry_buckets, _, geometry_item_bucket = _popularity_deciles(\n1322:             geometry_popularity\n1323:         )\n1324:         geometry_bucket_padded_t = torch.as_tensor(geometry_buckets, device=device)\n1325:         geometry_item_bucket_t = torch.as_tensor(geometry_item_bucket, device=device)\n1326:     all_embeddings = torch.from_numpy(embeddings)\n1327:     train_embeddings = all_embeddings[torch.from_numpy(train_ids)]\n1328:     # iter48's full transition stream, drawn by its own sampler so the item\n1329:     # batch above keeps exactly the rows, order and Sinkhorn balancing the\n1330:     # baseline sees.\n1331:     pair_dataset = TransitionPairs(train_frame)\n1332:     successor_indicator = (\n1333:         _successor_indicator(train_frame, len(embeddings))\n1334:         if FALSE_NEGATIVE_MASK\n1335:         else None\n1336:     )\n1337:     _hyp_degrees = None\n1338:     if _HYP_CONFIG is not Non